     1	static int pit_ioport_read(struct kvm_io_device *this,
     2				   gpa_t addr, int len, void *data)
     3	{
     4		struct kvm_pit *pit = dev_to_pit(this);
     5		struct kvm_kpit_state *pit_state = &pit->pit_state;
     6		struct kvm *kvm = pit->kvm;
     7		int ret, count;
     8		struct kvm_kpit_channel_state *s;
     9		if (!pit_in_range(addr))
    10			return -EOPNOTSUPP;
    11	
    12		addr &= KVM_PIT_CHANNEL_MASK;
    13		if (addr == 3)
    14			return 0;
    15	
    16		s = &pit_state->channels[addr];
    17	
    18		mutex_lock(&pit_state->lock);
    19	
    20		if (s->status_latched) {
    21			s->status_latched = 0;
    22			ret = s->status;
    23		} else if (s->count_latched) {
    24			switch (s->count_latched) {
    25			default:
    26			case RW_STATE_LSB:
    27				ret = s->latched_count & 0xff;
    28				s->count_latched = 0;
    29				break;
    30			case RW_STATE_MSB:
    31				ret = s->latched_count >> 8;
    32				s->count_latched = 0;
    33				break;
    34			case RW_STATE_WORD0:
    35				ret = s->latched_count & 0xff;
    36				s->count_latched = RW_STATE_MSB;
    37				break;
    38			}
    39		} else {
    40			switch (s->read_state) {
    41			default:
    42			case RW_STATE_LSB:
    43				count = pit_get_count(kvm, addr);
    44				ret = count & 0xff;
    45				break;
    46			case RW_STATE_MSB:
    47				count = pit_get_count(kvm, addr);
    48				ret = (count >> 8) & 0xff;
    49				break;
    50			case RW_STATE_WORD0:
    51				count = pit_get_count(kvm, addr);
    52				ret = count & 0xff;
    53				s->read_state = RW_STATE_WORD1;
    54				break;
    55			case RW_STATE_WORD1:
    56				count = pit_get_count(kvm, addr);
    57				ret = (count >> 8) & 0xff;
    58				s->read_state = RW_STATE_WORD0;
    59				break;
    60			}
    61		}
    62	
    63		if (len > sizeof(ret))
    64			len = sizeof(ret);
    65		memcpy(data, (char *)&ret, len);
    66	
    67		mutex_unlock(&pit_state->lock);
    68		return 0;
    69	}
